import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.hwbV7reR.js";const m=JSON.parse('{"title":"План модернизации","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1791695486000}'),i={name:"roadmap.md"};function p(n,e,l,h,s,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="план-модернизации" tabindex="-1">План модернизации <a class="header-anchor" href="#план-модернизации" aria-label="Permalink to &quot;План модернизации&quot;">​</a></h1><p>Публичный вход уже подготовлен: README, MIT, инструкции, OpenAPI, контрактные проверки и сайт VitePress. Ниже — последовательность дальнейших изменений. Запланированная возможность не считается доступной до реализации и проверок.</p><h2 id="_1-архитектурныи-контракт" tabindex="-1">1. Архитектурный контракт <a class="header-anchor" href="#_1-архитектурныи-контракт" aria-label="Permalink to &quot;1. Архитектурный контракт&quot;">​</a></h2><p>Зафиксировать границы слоёв, состояния и идентификаторы, гарантии повторов/отзыва, секретные данные и правила совместимости. В CI проверять зависимости модулей; существующие отклонения перечислить точно и удалять по мере рефакторинга.</p><p>Материалы этапа: <a href="./architecture.html">архитектура</a>, <a href="./lifecycle.html">жизненный цикл</a>, <a href="./compatibility.html">совместимость</a>, <a href="./security.html">безопасность</a>, <code>contracts/architecture.json</code>, <code>scripts/check_architecture.py</code>.</p><p>Критерий: новая запрещённая зависимость блокируется проверкой, существующий долг явно описан, гарантии сопоставлены с регрессионными тестами.</p><h2 id="_2-наблюдаемость" tabindex="-1">2. Наблюдаемость <a class="header-anchor" href="#_2-наблюдаемость" aria-label="Permalink to &quot;2. Наблюдаемость&quot;">​</a></h2><p>Идентификаторы запросов и операций, безопасные структурированные события, причины ошибок и измерения этапов. Метрики очереди незавершённых операций и восстановления. Токены, приватные документы и произвольный upstream-текст не попадают в логи; идентификаторы устройств не становятся метками метрик.</p><p>Материалы этапа: <a href="./observability.html">диагностика и метрики</a>, порт telemetry, JSON/Prometheus-реализация и tests/test_observability.py. Критерий: задержка или сбой объясняются по идентификатору операции без доступа к ключам.</p><h2 id="_3-нагрузка-и-сроки-выполнения" tabindex="-1">3. Нагрузка и сроки выполнения <a class="header-anchor" href="#_3-нагрузка-и-сроки-выполнения" aria-label="Permalink to &quot;3. Нагрузка и сроки выполнения&quot;">​</a></h2><p>Переиспользовать HTTP-клиент, ограничить параллельность всего процесса и каждого узла, задать общий срок операции. Повторы ограничены и сохраняют ключ операции. После неопределённого результата нельзя создавать новый доступ на другом узле.</p><p>Материалы этапа: <a href="./runtime-limits.html">лимиты и сроки</a>, execution, HTTPPool, политика agents и tests/test_runtime_limits.py.</p><p>Критерий: медленный агент не исчерпывает ресурсы процесса; нагрузочные проверки и сценарии потери ответа подтверждают ограничения и отсутствие дублирующих peer.</p><h2 id="_4-границы-реализации-и-типизированные-контракты" tabindex="-1">4. Границы реализации и типизированные контракты <a class="header-anchor" href="#_4-границы-реализации-и-типизированные-контракты" aria-label="Permalink to &quot;4. Границы реализации и типизированные контракты&quot;">​</a></h2><p>Извлечь SQL в узкие хранилища, сохраняя общие транзакции и межпроцессные блокировки. Сборку конкретных драйверов сосредоточить в bootstrap. Разделить чтение настроек и проверку runtime-возможностей. Отделить lease transport от Amnezia-agent. Заменить неструктурированные dict/строки на модели и перечисления; добавить проверку типов. Использовать единые определения валидации и OpenAPI. Выделить общий набор контрактных испытаний драйверов. Удалить соответствующие исключения импортов.</p><p>Реализовано: узкие порты журналов и отдельные SQLite-репозитории, сборка в bootstrap, LeaseTransport, типизированные записи и mypy в CI. Все 20 исключений импортов удалены. Модели мутаций общие для runtime/OpenAPI; добавлены испытания драйверов и отката транзакции переключения. Включено в выпуск 0.4.0.</p><p>Критерий: прежние гарантии жизненного цикла сохранены; прикладные сценарии не знают конкретный драйвер или SQLite. Параметризованные проверки пригодны второму протоколу.</p><h2 id="_5-предсказуемое-обновление" tabindex="-1">5. Предсказуемое обновление <a class="header-anchor" href="#_5-предсказуемое-обновление" aria-label="Permalink to &quot;5. Предсказуемое обновление&quot;">​</a></h2><p>Явные версии схемы, матрица миграций поддерживаемых релизов, испытания резервного копирования и восстановления, совместимость агента и контроллера. Откат программы проверяется отдельно от восстановления БД после мутаций узлов.</p><p>Реализовано в 0.4.0: версия схемы 1 и атомарная миграция известных журналов, контракт совместимости релиза, две репетиции миграции при обновлении, проверка отката кода. Backup с манифестом и контрольными суммами восстанавливается в отдельный каталог с блокировкой запуска до операторской сверки узлов. Добавлены тесты успешного обновления, отказов и восстановления незавершённых операций.</p><p>Критерий: успешное и неуспешное обновление воспроизводятся автоматически с сохранением идентичности, отключённого доступа и незавершённых операций.</p><h2 id="_6-панель-просмотра" tabindex="-1">6. Панель просмотра <a class="header-anchor" href="#_6-панель-просмотра" aria-label="Permalink to &quot;6. Панель просмотра&quot;">​</a></h2><p>Самостоятельная веб-панель: серверы, технические назначения, события, длительность операций. Отдельный административный API и авторизация; локальный доступ по умолчанию. Админка Undercore не является зависимостью панели.</p><p>Реализовано в 0.4.0: отдельный процесс <code>panel</code>, собственный ключ и часовые сессии, read-only снимки SQLite, ограниченный журнал событий API/worker, страницы серверов, назначений и длительности этапов. Проверки покрывают изоляцию авторизации, CSRF/Host, отсутствие секретов и мутаций, ротацию событий и пагинацию. Инструкция: <a href="./panel.html">панель просмотра</a>. Панель запускается отдельно от API; установка службы панели необязательна.</p><p>Критерий: оператор видит состояние системы, секретные документы не передаются в браузер для построения обзора, сервисный backend-токен не открывает администрирование.</p><h2 id="_7-управление-и-выпуск" tabindex="-1">7. Управление и выпуск <a class="header-anchor" href="#_7-управление-и-выпуск" aria-label="Permalink to &quot;7. Управление и выпуск&quot;">​</a></h2><p>Добавление серверов, режим прекращения новых выдач, изменение политик и отзыв доступа через общие сценарии CLI и GUI с журналом действий. Усиление CI: проверка зависимостей, поиск секретов, поддерживаемые версии Python, закреплённые CI-действия, проверяемое происхождение артефактов. Независимые проверки безопасности можно добавлять раньше.</p><p>Критерий: одинаковые операции CLI и GUI сохраняют одинаковые гарантии; выпуск проходит обязательные проверки до развёртывания.</p><p>Реализовано в 0.4.0: команды CLI/GUI через общий Administration, проверка ревизий, долговечный журнал намерений и результатов, добавление готового агента, режим/лимит узла, отзыв доступа и атомарная запись политик с применением после перезапуска. Режим управления панели включается явно. CI закреплён по SHA, настроены Python 3.12–3.14, поиск секретов, проверка зависимостей и attestation архива до публикации. <a href="./panel.html#управление">Управление</a>, <a href="./release-security.html">проверки выпуска</a>. Публикация проходит через GitHub Actions; развёртывание выполняется отдельной командой оператора после проверки происхождения архива.</p><h2 id="после-модернизации-второи-протокол" tabindex="-1">После модернизации: второй протокол <a class="header-anchor" href="#после-модернизации-второи-протокол" aria-label="Permalink to &quot;После модернизации: второй протокол&quot;">​</a></h2><p>Первый этап: <a href="./trusttunnel.html">реальные испытания TrustTunnel</a>, проверяемый адаптер TOML и воспроизводимый SOCKS-probe. NodeDriver и динамический агент ещё не готовы.</p><p>TrustTunnel: отдельный стенд, проверка возможностей реального API, адаптер полного жизненного цикла, поддержка в клиенте и общие контрактные испытания. Сначала явный выбор протокола; автоматическая межпротокольная миграция проектируется отдельно.</p><h2 id="параллельное-направление-самостоятельныи-vpn-узел" tabindex="-1">Параллельное направление: самостоятельный VPN-узел <a class="header-anchor" href="#параллельное-направление-самостоятельныи-vpn-узел" aria-label="Permalink to &quot;Параллельное направление: самостоятельный VPN-узел&quot;">​</a></h2><p>Выделить API/agent/runtime и тесты в публичный UndercoreCo/vpn-node, сохраняя разделение привилегий и действующий контракт. Переносить исходники по allowlist без серверных настроек и журналов, сохранять происхождение и лицензии компонентов.</p><p>Проверить установку и повторный запуск на чистой поддерживаемой Linux VM, создание/экспорт/отзыв peer и сохранение ключей при обновлении. Installer должен останавливаться при конфликте с чужим VPN. Регистрация готового API (<code>add server</code>) и установка по SSH (<code>provision server</code>, пока не реализована) — разные операции. SSH не становится runtime-зависимостью выдачи подключения.</p>',35)])])}const u=a(i,[["render",p]]);export{m as __pageData,u as default};
